from __future__ import annotations

import json
import math
from pathlib import Path

from workflow.compare_periodic_representations import compare_representations


TASK_DIR = Path(__file__).resolve().parent
REPORT_FILE = TASK_DIR / "outputs" / "public_reproduction_report.json"
SUCCESS_TOLERANCE_HARTREE = 5.0e-5


def write_report(report: dict[str, object], exit_code: int) -> int:
    REPORT_FILE.parent.mkdir(exist_ok=True)
    payload = json.dumps(report, indent=2, sort_keys=True) + "\n"
    REPORT_FILE.write_text(payload, encoding="utf-8")
    print(payload, end="")
    return exit_code


def main() -> int:
    try:
        comparison = compare_representations()
    except Exception as exc:  # noqa: BLE001 - infrastructure failures need a report.
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )

    values = (
        comparison.primitive_kpoint_energy,
        comparison.gamma_supercell_energy_per_primitive,
        comparison.absolute_disagreement,
    )
    finite = all(math.isfinite(value) for value in values)
    converged = comparison.primitive_converged and comparison.supercell_converged
    success = (
        finite
        and converged
        and comparison.absolute_disagreement <= SUCCESS_TOLERANCE_HARTREE
    )
    report = {
        "schema_version": "1.0",
        "status": "post_fix_success" if success else "pre_fix_expected_failure",
        "observation": {
            "primitive_kpoint_total_energy_hartree_per_cell": (
                comparison.primitive_kpoint_energy
            ),
            "gamma_supercell_total_energy_hartree_per_cell": (
                comparison.gamma_supercell_energy_per_primitive
            ),
            "absolute_disagreement_hartree_per_cell": (
                comparison.absolute_disagreement
            ),
            "both_converged": converged,
            "finite": finite,
        },
    }
    return write_report(report, 0 if success else 1)


if __name__ == "__main__":
    raise SystemExit(main())

